{
  "name": "铭禾 MHS-5200A 双通道函数发生器",
  "name_en": "Minghe MHS-5200A Dual-Channel Function Generator",
  "manufacturer": "Minghe",
  "description": "MHS-5200A 是一款低成本双通道函数发生器，可输出常见测试波形，用于电子实验、教学演示、信号注入和台式电路调试。它适合为被测电路提供可调频率、相位、偏置和占空比的激励信号。",
  "description_en": "The MHS-5200A is a low-cost dual-channel function generator that outputs common test waveforms for electronics experiments, teaching, signal injection, and bench-top circuit debugging. It is used to provide adjustable excitation signals with controllable frequency, phase, offset, and duty cycle.",
  "tag_hints": [
    "function generator",
    "dual-channel waveform output",
    "bench signal source",
    "frequency control",
    "phase adjustment",
    "duty cycle control",
    "electronics lab"
  ],
  "actions": [
    {
      "action_name": "auto-channel",
      "description": "获取指定通道",
      "description_en": "Get a specified channel"
    },
    {
      "action_name": "auto-serial_number",
      "description": "获取序列号",
      "description_en": "Get serial number"
    },
    {
      "action_name": "auto-duty_cycle",
      "description": "获取/设置占空比",
      "description_en": "Get/set duty cycle"
    },
    {
      "action_name": "auto-enable",
      "description": "获取/设置输出使能状态",
      "description_en": "Get/set output enable state"
    },
    {
      "action_name": "auto-frequency",
      "description": "获取/设置输出频率",
      "description_en": "Get/set output frequency"
    },
    {
      "action_name": "auto-offset",
      "description": "获取/设置直流偏置",
      "description_en": "Get/set DC offset"
    },
    {
      "action_name": "auto-phase",
      "description": "获取/设置相位",
      "description_en": "Get/set phase"
    },
    {
      "action_name": "auto-function",
      "description": "获取/设置波形类型",
      "description_en": "Get/set waveform function"
    }
  ]
}

